const menu=[
{id:'chicken',name:'Fried Chicken',category:'ayam',tag:'RASA KHAS d’BESTO',description:'Ayam goreng d’Besto. Tanyakan pilihan potongan dan paket yang tersedia di outlet.'},
{id:'geprek',name:'Ayam Geprek',category:'ayam',tag:'BUAT PENCINTA SAMBAL',description:'Pilihan ayam geprek untuk kamu yang suka makan dengan sambal. Konfirmasikan variasi yang tersedia kepada tim.'},
{id:'sadas',name:'SADAS',category:'ayam',tag:'PILIHAN AYAM',description:'Olahan ayam bersaus dalam pilihan menu d’Besto. Tanyakan detail rasa dan ketersediaannya di outlet.'},
{id:'burger',name:'Burger',category:'burger',tag:'TEMAN NONGKRONG',description:'Ragam pilihan burger dalam dokumentasi menu d’Besto. Tanyakan varian regular dan cheese yang tersedia.'},
{id:'spaghetti',name:'Spaghetti',category:'pelengkap',tag:'VARIASI PILIHAN',description:'Pilihan spaghetti untuk melengkapi waktu makan. Konfirmasikan varian dan ketersediaan di outlet tujuan.'},
{id:'drinks',name:'Minuman',category:'pelengkap',tag:'LENGKAPI MOMENMU',description:'Pilihan minuman pendamping menu favoritmu. Tanyakan ragam minuman terkini di outlet.'}
];
const grid=document.querySelector('#menu-grid');
function renderMenu(filter='all'){grid.replaceChildren();menu.filter(m=>filter==='all'||m.category===filter).forEach(m=>{const article=document.createElement('article');article.className='menu-card';article.innerHTML=`<div class="menu-image-wrap"><img class="menu-image" src="assets/${m.id}.png" alt="${m.name} dari dokumentasi menu d’Besto" loading="lazy"><span class="tag">${m.tag}</span></div><div class="menu-info"><div><h3>${m.name}</h3><p>${m.category==='ayam'?'Kenali pilihan ayam favoritmu.':m.category==='burger'?'Praktis untuk teman kumpul.':'Teman untuk menu favorit.'}</p></div><button aria-label="Lihat detail ${m.name}" data-menu="${m.id}">↗</button></div>`;grid.append(article)})}
renderMenu();document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});renderMenu(button.dataset.filter)}));
const dialog=document.querySelector('#menu-dialog');grid.addEventListener('click',e=>{const button=e.target.closest('[data-menu]');if(!button)return;const m=menu.find(x=>x.id===button.dataset.menu);document.querySelector('#detail-image').src=`assets/${m.id}.png`;document.querySelector('#detail-image').alt=m.name;document.querySelector('#detail-title').textContent=m.name;document.querySelector('#detail-description').textContent=m.description;document.querySelector('#detail-wa').href='https://wa.me/6281223457871?text='+encodeURIComponent(`Halo tim d’Besto, saya ingin bertanya tentang ${m.name}. Mohon informasi harga dan ketersediaannya.`);dialog.showModal()});dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
const toggle=document.querySelector('.nav-toggle'),nav=document.querySelector('nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Tutup navigasi':'Buka navigasi');toggle.textContent=open?'✕':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰'}));document.querySelectorAll('[data-intent]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#topic').value=a.dataset.intent}));document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#name').value.trim(),message=document.querySelector('#message').value.trim();if(!name||!message)return;const topic=document.querySelector('#topic').value;window.open('https://wa.me/6281223457871?text='+encodeURIComponent(`Halo tim d’Besto, saya ${name}.\nTopik: ${topic}\n\n${message}`),'_blank','noopener,noreferrer')});document.querySelector('#year').textContent=new Date().getFullYear();
